        break;

      case "equip": {
        const drop = resolveEquipEntry(entry, rng, opts, weaponRef, false);
        if (drop) results.push(drop);
        break;
      }

      case "generated": {
        const drop = resolveEquipEntry(entry, rng, opts, weaponRef, true);
        if (drop) results.push(drop);
        break;
      }

      case "item":
        results.push({ kind: "item", params: { itemId: entry.itemId } });
